<div class="d-flex justify-content-between"><h3 class="h6">Itinerary days</h3><button type="button" class="btn btn-sm btn-outline-success" data-repeater-add="itinerary-rows" data-template="itinerary-template">Add day</button></div><div id="itinerary-rows" data-next-index="{{ $package?->itineraries->count()??0 }}">@foreach($package?->itineraries??[] as $i=>$day)<div class="border rounded p-3 my-2" data-repeater-row><input type="hidden" name="itineraries[{{ $i }}][id]" value="{{ $day->id }}"><div class="row g-2"><div class="col-md-1"><input class="form-control" type="number" name="itineraries[{{ $i }}][day_number]" value="{{ $day->day_number }}" placeholder="Day"></div><div class="col-md-4"><input class="form-control" name="itineraries[{{ $i }}][title]" value="{{ $day->title }}" placeholder="Title"></div><div class="col-md-2"><input class="form-control" name="itineraries[{{ $i }}][destination_name]" value="{{ $day->destination_name }}" placeholder="Destination"></div><div class="col-md-2"><input class="form-control" name="itineraries[{{ $i }}][accommodation_name]" value="{{ $day->accommodation_name }}" placeholder="Accommodation"></div><div class="col-md-2"><input class="form-control" name="itineraries[{{ $i }}][meals]" value="{{ $day->meals }}" placeholder="Meals"></div><div class="col-md-1"><input class="form-control" type="number" name="itineraries[{{ $i }}][display_order]" value="{{ $day->display_order }}"></div><div class="col-12"><textarea class="form-control" name="itineraries[{{ $i }}][description]" placeholder="Description">{{ $day->description }}</textarea></div><div class="col-md-10"><input class="form-control" type="file" name="itineraries[{{ $i }}][image]" accept="image/jpeg,image/png,image/webp">@if($day->image_path)<small>Current image: {{ basename($day->image_path) }}</small>@endif</div><div class="col-md-2"><label class="text-danger"><input type="checkbox" name="itineraries[{{ $i }}][_remove]" value="1"> Remove day</label></div></div></div>@endforeach</div><template id="itinerary-template"><div class="border rounded p-3 my-2" data-repeater-row><div class="row g-2"><div class="col-md-1"><input class="form-control" type="number" name="itineraries[__INDEX__][day_number]" placeholder="Day" required></div><div class="col-md-4"><input class="form-control" name="itineraries[__INDEX__][title]" placeholder="Title" required></div><div class="col-md-2"><input class="form-control" name="itineraries[__INDEX__][destination_name]" placeholder="Destination"></div><div class="col-md-2"><input class="form-control" name="itineraries[__INDEX__][accommodation_name]" placeholder="Accommodation"></div><div class="col-md-2"><input class="form-control" name="itineraries[__INDEX__][meals]" placeholder="Meals"></div><div class="col-md-1"><input class="form-control" type="number" name="itineraries[__INDEX__][display_order]" value="0"></div><div class="col-12"><textarea class="form-control" name="itineraries[__INDEX__][description]" placeholder="Description"></textarea></div><div class="col-md-10"><input class="form-control" type="file" name="itineraries[__INDEX__][image]"></div><div class="col-md-2"><button class="btn btn-outline-danger" type="button" data-remove-new-row>Remove</button></div></div></div></template>
